describe('HTTP Status Codes Verification', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com/status_codes');
    });

    it('should navigate to 200 status code page and verify content', () => {
        cy.contains('200').click();
        cy.url().should('include', '/status_codes/200');
        cy.contains('This page returned a 200 status code').should('be.visible');
    });

    it('should navigate to 404 status code page and verify content', () => {
        cy.go('back');
        cy.contains('404').click();
        cy.url().should('include', '/status_codes/404');
        cy.contains('This page returned a 404 status code').should('be.visible');
    });
});
